//! About page: version, licence and the third-party licence texts.

use crate::widgets;
use egui::{RichText, ScrollArea, Ui};
use std::sync::LazyLock;

/// Notices for the bundled fonts.
const FONT_NOTICE: &str = include_str!("../../assets/THIRD_PARTY.txt");

/// Licence texts of every Rust dependency, generated by cargo-about.
const CRATE_LICENCES: &str = include_str!("../../assets/DEPENDENCIES.txt");

static CRATE_LINES: LazyLock<Vec<&str>> = LazyLock::new(|| CRATE_LICENCES.lines().collect());

const CHANGELOG: &str = include_str!("../../../../CHANGELOG.md");

/// Turns the changelog into plain text: no title, heading marks or dashes.
fn plain(markdown: &str) -> String {
    markdown
        .lines()
        .filter(|line| !line.starts_with("# "))
        .map(|line| {
            let text = line.trim_start_matches('#').trim_start();
            text.strip_prefix("- ")
                .map_or_else(|| text.to_owned(), |item| format!("\u{2022} {item}"))
        })
        .collect::<Vec<_>>()
        .join("\n")
}

/// Draws the version, the project licence and the bundled licence texts.
pub fn show(ui: &mut Ui) {
    crate::widgets::section(ui, "Changelog", |ui| {
        ui.label(crate::widgets::muted(ui, &plain(CHANGELOG)));
    });
    ui.add_space(16.0);
    widgets::card(ui, |ui| {
        ui.label(RichText::new(format!("KeyMagic {}", env!("CARGO_PKG_VERSION"))).strong());
        ui.label(widgets::muted(ui, "Licensed under GPL-2.0-only."));
        ui.add_space(8.0);
        ui.hyperlink_to(
            "Source code",
            "https://github.com/codewiththiha/keymagic-rs",
        );
    });
    ui.add_space(24.0);
    ui.label(RichText::new("Third-party licences").strong());
    ui.add_space(8.0);
    widgets::card(ui, |ui| {
        ui.label(widgets::muted(ui, FONT_NOTICE));
        ui.add_space(8.0);
        let row_height = ui.text_style_height(&egui::TextStyle::Monospace);
        ScrollArea::vertical().max_height(360.0).show_rows(
            ui,
            row_height,
            CRATE_LINES.len(),
            |ui, rows| {
                for line in &CRATE_LINES[rows] {
                    ui.label(RichText::new(*line).monospace());
                }
            },
        );
    });
}

#[cfg(test)]
mod tests {
    use super::plain;

    #[test]
    fn crate_licences_list_each_dependency_licence() {
        let lines = super::CRATE_LICENCES.lines();
        assert!(lines.clone().any(|line| line == "# Third-party licences"));
        assert!(lines.clone().any(|line| line.starts_with("## ")));
        assert!(super::CRATE_LICENCES.contains("target-lexicon 0.12.16"));
    }

    #[test]
    fn changelog_drops_the_title_and_marks_bullets() {
        assert_eq!(
            plain("# Changelog\n\n## Unreleased\n\n- one"),
            "\nUnreleased\n\n\u{2022} one"
        );
    }
}
